diff --git a/scripts/generar-seo.mjs b/scripts/generar-seo.mjs
index d3f9aef..571b9bf 100644
--- a/scripts/generar-seo.mjs
+++ b/scripts/generar-seo.mjs
@@ -56,3 +56,16 @@ for (const { route, destination, html } of pages) {
   fs.writeFileSync(destination, html, "utf8");
   console.log("SEO generado: " + route + " -> " + destination);
 }
+
+// Build the sitemap from the same canonical URLs used by React and the HTML heads.
+const sitemap = [
+  '<?xml version="1.0" encoding="UTF-8"?>',
+  '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">',
+  ...Object.keys(SEO_PAGES).map((route) =>
+    "  <url><loc>" + escapeHtml(getSeoPage(route).canonical) + "</loc></url>"
+  ),
+  "</urlset>",
+  "",
+].join("\n");
+fs.writeFileSync(path.join(outputDir, "sitemap.xml"), sitemap, "utf8");
+console.log("Sitemap generado: " + path.join(outputDir, "sitemap.xml"));
diff --git a/src/data/seo.js b/src/data/seo.js
index dec22dc..52d4494 100644
--- a/src/data/seo.js
+++ b/src/data/seo.js
@@ -32,6 +32,8 @@ export const SHARE_IMAGE = {
 };

 export function getSeoPage(pathname) {
-  const route = Object.hasOwn(SEO_PAGES, pathname) ? pathname : "/";
-  return { ...SEO_PAGES[route], canonical: SITE_URL + route, image: SHARE_IMAGE };
+  const normalizedPathname = pathname.replace(/\/+$/, "") || "/";
+  const route = Object.hasOwn(SEO_PAGES, normalizedPathname) ? normalizedPathname : "/";
+  const canonical = SITE_URL + (route === "/" ? "/" : route + "/");
+  return { ...SEO_PAGES[route], canonical, image: SHARE_IMAGE };
 }
